CREATE TABLE IF NOT EXISTS car (id TEXT PRIMARY KEY, name TEXT NOT NULL, manufacturer TEXT, model TEXT, scale TEXT, notes TEXT, created_at TEXT NOT NULL, archived_at TEXT);
CREATE TABLE IF NOT EXISTS component (id TEXT PRIMARY KEY, car_id TEXT NOT NULL REFERENCES car(id), slot TEXT NOT NULL, name TEXT NOT NULL, serial_number TEXT, notes TEXT, installed_at TEXT NOT NULL, removed_at TEXT);
CREATE TABLE IF NOT EXISTS drive_session (id TEXT PRIMARY KEY, car_id TEXT NOT NULL REFERENCES car(id), started_at TEXT NOT NULL, duration_minutes INTEGER, conditions TEXT, notes TEXT);
CREATE TABLE IF NOT EXISTS maintenance_plan (id TEXT PRIMARY KEY, car_id TEXT NOT NULL REFERENCES car(id), component_id TEXT NOT NULL REFERENCES component(id), name TEXT NOT NULL, interval_days INTEGER, interval_sessions INTEGER, baseline_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', paused_at TEXT);
CREATE TABLE IF NOT EXISTS service_record (id TEXT PRIMARY KEY, car_id TEXT NOT NULL REFERENCES car(id), component_id TEXT REFERENCES component(id), performed_at TEXT NOT NULL, description TEXT NOT NULL, baseline_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS photo (id TEXT PRIMARY KEY, car_id TEXT NOT NULL REFERENCES car(id), object_key TEXT NOT NULL UNIQUE, content_type TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS component_car_slot_idx ON component(car_id, slot);
CREATE INDEX IF NOT EXISTS drive_session_car_started_idx ON drive_session(car_id, started_at);
CREATE TABLE IF NOT EXISTS owner (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, email_verified INTEGER NOT NULL DEFAULT 0, image TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS session (id TEXT PRIMARY KEY, expires_at INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, ip_address TEXT, user_agent TEXT, user_id TEXT NOT NULL REFERENCES owner(id));
CREATE TABLE IF NOT EXISTS account (id TEXT PRIMARY KEY, account_id TEXT NOT NULL, provider_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES owner(id), access_token TEXT, refresh_token TEXT, id_token TEXT, access_token_expires_at INTEGER, refresh_token_expires_at INTEGER, scope TEXT, password TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expires_at INTEGER NOT NULL, created_at INTEGER, updated_at INTEGER);
CREATE TABLE IF NOT EXISTS passkey (id TEXT PRIMARY KEY, name TEXT, public_key TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES owner(id), credential_id TEXT NOT NULL UNIQUE, counter INTEGER NOT NULL DEFAULT 0, device_type TEXT, backed_up INTEGER NOT NULL DEFAULT 0, transports TEXT, created_at INTEGER, aaguid TEXT);
